CREATE EXTENSION IF NOT EXISTS citext;


CREATE TABLE "Agents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(120) NOT NULL,
    "Active" boolean NOT NULL,
    CONSTRAINT "PK_Agents" PRIMARY KEY ("Id")
);


CREATE TABLE "AuditLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ActorId" integer,
    "ActorUsername" character varying(80) NOT NULL,
    "Action" character varying(50) NOT NULL,
    "TargetType" character varying(50) NOT NULL,
    "TargetId" character varying(80),
    "Details" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
);


CREATE TABLE "Products" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Sku" character varying(50) NOT NULL,
    "Description" text NOT NULL,
    "CurrentStock" integer NOT NULL,
    "Threshold" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Products" PRIMARY KEY ("Id")
);


CREATE TABLE "Services" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(120) NOT NULL,
    "Active" boolean NOT NULL,
    CONSTRAINT "PK_Services" PRIMARY KEY ("Id")
);


CREATE TABLE "Suppliers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(120) NOT NULL,
    "Active" boolean NOT NULL,
    CONSTRAINT "PK_Suppliers" PRIMARY KEY ("Id")
);


CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" citext NOT NULL,
    "DisplayName" character varying(120) NOT NULL,
    "PasswordHash" text NOT NULL,
    "Role" character varying(20) NOT NULL,
    "Active" boolean NOT NULL,
    "DashboardPeriod" character varying(20) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "LastLoginAt" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);


CREATE TABLE "Alerts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" integer NOT NULL,
    "AlertType" character varying(50) NOT NULL,
    "Message" text NOT NULL,
    "IsResolved" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Alerts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Alerts_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Movements" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" integer NOT NULL,
    "QuantityChange" integer NOT NULL,
    "MovementType" character varying(10) NOT NULL,
    "UnitPrice" numeric(12,2) NOT NULL,
    "TaxRate" numeric(5,2) NOT NULL,
    "SupplierId" integer,
    "AgentId" integer,
    "ServiceId" integer,
    "LegacyText" character varying(500) NOT NULL,
    "Reason" character varying(255) NOT NULL,
    "RecordedBy" character varying(80) NOT NULL,
    "Timestamp" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Movements" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Movements_Agents_AgentId" FOREIGN KEY ("AgentId") REFERENCES "Agents" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Movements_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Movements_Services_ServiceId" FOREIGN KEY ("ServiceId") REFERENCES "Services" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Movements_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE RESTRICT
);


CREATE UNIQUE INDEX "IX_Agents_Name" ON "Agents" ("Name");


CREATE INDEX "IX_Alerts_CreatedAt" ON "Alerts" ("CreatedAt");


CREATE INDEX "IX_Alerts_ProductId" ON "Alerts" ("ProductId");


CREATE INDEX "IX_AuditLogs_Action" ON "AuditLogs" ("Action");


CREATE INDEX "IX_AuditLogs_ActorId" ON "AuditLogs" ("ActorId");


CREATE INDEX "IX_AuditLogs_CreatedAt" ON "AuditLogs" ("CreatedAt");


CREATE INDEX "IX_AuditLogs_TargetType" ON "AuditLogs" ("TargetType");


CREATE INDEX "IX_Movements_AgentId" ON "Movements" ("AgentId");


CREATE INDEX "IX_Movements_ProductId" ON "Movements" ("ProductId");


CREATE INDEX "IX_Movements_ServiceId" ON "Movements" ("ServiceId");


CREATE INDEX "IX_Movements_SupplierId" ON "Movements" ("SupplierId");


CREATE INDEX "IX_Movements_Timestamp" ON "Movements" ("Timestamp");


CREATE UNIQUE INDEX "IX_Products_Name" ON "Products" ("Name");


CREATE UNIQUE INDEX "IX_Products_Sku" ON "Products" ("Sku");


CREATE UNIQUE INDEX "IX_Services_Name" ON "Services" ("Name");


CREATE UNIQUE INDEX "IX_Suppliers_Name" ON "Suppliers" ("Name");


CREATE UNIQUE INDEX "IX_Users_Username" ON "Users" ("Username");



